<script setup lang="ts">
definePageMeta({ layout: 'dashboard', middleware: 'auth' })

const auth = useAuthStore()
const editMode = ref(false)
const saving = ref(false)
const saved = ref(false)
const pwModal = ref(false)
const pwError = ref('')
const pwSaving = ref(false)

const form = reactive({
  name: auth.user?.name ?? '',
  nis: auth.user?.nis ?? '',
  class: auth.user?.class ?? '',
  phone: auth.user?.phone ?? ''
})

async function save() {
  saving.value = true
  try {
    const res = await $fetch<{ id: string; name: string }>('/api/siswa/profile', {
      method: 'PUT',
      body: { name: form.name, phone: form.phone, class: form.class }
    })
    if (auth.user) auth.user.name = res.name
    saved.value = true
    editMode.value = false
    setTimeout(() => saved.value = false, 2000)
  } catch (e: any) {
    alert(e.data?.message || 'Gagal menyimpan profil')
  } finally {
    saving.value = false
  }
}

const pwForm = reactive({ oldPassword: '', newPassword: '', confirmPassword: '' })

async function changePassword() {
  pwError.value = ''
  if (pwForm.newPassword !== pwForm.confirmPassword) {
    pwError.value = 'Konfirmasi password tidak cocok.'
    return
  }
  if (pwForm.newPassword.length < 6) {
    pwError.value = 'Password baru minimal 6 karakter.'
    return
  }
  pwSaving.value = true
  try {
    await $fetch('/api/siswa/change-password', {
      method: 'POST',
      body: { oldPassword: pwForm.oldPassword, newPassword: pwForm.newPassword }
    })
    pwModal.value = false
    pwForm.oldPassword = ''
    pwForm.newPassword = ''
    pwForm.confirmPassword = ''
    alert('Password berhasil diubah!')
  } catch (e: any) {
    pwError.value = e.data?.message || 'Gagal mengubah password'
  } finally {
    pwSaving.value = false
  }
}
</script>

<template>
